1	"use client";
2	/**
3	 * The whole app (U1): side nav (this browser's chats) · chat · widgets.
4	 * Talks ONLY to our API (requirement 6): /api/chat (streaming), /api/widgets,
5	 * /api/chat/sessions and /api/chat/history.
6	 */
7	import { useChat } from "@ai-sdk/react";
8	import { DefaultChatTransport } from "ai";
9	import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
10	import type { SneakoscopeDataParts, SneakoscopeUIMessage } from "@/core/api/chatStream";
11	import type { TranscriptTurn } from "@/core/db/chatTranscript";
12	import { userError } from "@/core/errors/userErrors";
13	import type { WidgetsData } from "@/core/widgets/widgetsData";
14	import { speak, stopSpeaking } from "../_lib/speech";
15	import { EMPTY_IDS, rememberSession, sessionIdsSnapshot, subscribeToStorage } from "../_lib/storage";
16	import { AssistantMessage } from "./answer/AssistantMessage";
17	import { ErrorCard } from "./answer/ErrorCard";
18	import { Composer } from "./Composer";
19	import { EmptyState } from "./EmptyState";
20	import { Footer } from "./Footer";
21	import { Header } from "./Header";
22	import { Pane } from "./Pane";
23	import { SideNav } from "./SideNav";
24	import { TabBar, type ShellTab } from "./TabBar";
25	import { WidgetsRail } from "./WidgetsRail";
26	
27	/** Text of a user message. */
28	function textOf(message: SneakoscopeUIMessage | undefined): string {
29	  return message?.parts.map((part) => (part.type === "text" ? part.text : "")).join("") ?? "";
30	}
31	
32	/** Friendly error from a failed request (the API answers with `{ error: {...} }`). */
33	function requestError(error: Error): SneakoscopeDataParts["error"] {
34	  try {
35	    const parsed = JSON.parse(error.message) as { error?: SneakoscopeDataParts["error"] };
36	    if (parsed.error?.message) return parsed.error;
37	  } catch {
38	    // not JSON — e.g. the network dropped
39	  }
40	  const { code, message, hint, retryable } = userError("internal_error");
41	  return { code, message, hint, retryable };
42	}
43	
44	/** Rebuilds UI messages from a saved transcript (validated answers, as they were shown). */
45	function messagesFromTurns(turns: TranscriptTurn[]): SneakoscopeUIMessage[] {
46	  return turns.flatMap((turn, index) => [
47	    { id: `history-user-${index}`, role: "user" as const, parts: [{ type: "text" as const, text: turn.question }] },
48	    {
49	      id: `history-answer-${index}`,
50	      role: "assistant" as const,
51	      parts: [{ type: "data-answer" as const, id: "answer", data: turn.answer }],
52	    },
53	  ]);
54	}
55	
56	/** The app. */
57	export function SneakoscopeApp() {
58	  // Browser-remembered values, read hydration-safely (the server always renders the defaults).
59	  const sessionIds = useSyncExternalStore(subscribeToStorage, sessionIdsSnapshot, () => EMPTY_IDS);
60	  const [sessionId, setSessionId] = useState<string | null>(null);
61	  const [freshness, setFreshness] = useState<string | null>(null);
62	  const [hubCount, setHubCount] = useState<number | null>(null);
63	  const [tab, setTab] = useState<ShellTab>("chat");
64	  const [loadingChat, setLoadingChat] = useState(false);
65	  const scrollRef = useRef<HTMLDivElement>(null);
66	
67	  // sessionId travels with each sendMessage call (see ask); the transport only adds the message text. US units only (D126).
68	  const transport = useMemo(
69	    () =>
70	      new DefaultChatTransport<SneakoscopeUIMessage>({
71	        api: "/api/chat",
72	        prepareSendMessagesRequest: ({ messages, body }) => ({ body: { ...body, message: textOf(messages.at(-1)) } }),
73	      }),
74	    [],
75	  );
76	
77	  const { messages, sendMessage, setMessages, status, error, clearError, stop } = useChat<SneakoscopeUIMessage>({
78	    transport,
79	    onData: (part) => {
80	      if (part.type === "data-session") {
81	        setSessionId(part.data.sessionId);
82	        rememberSession(part.data.sessionId);
83	      }
84	    },
85	  });
86	  const busy = status === "submitted" || status === "streaming";
87	  /** True while the current question came from the mic (its answer will be read aloud). */
88	  const voiceTurn = useRef(false);
89	
90	  // Keep the newest message in view inside the conversation panel (the page itself never scrolls).
91	  useEffect(() => {
92	    const body = scrollRef.current;
93	    body?.scrollTo({ top: body.scrollHeight, behavior: "smooth" });
94	  }, [messages.length, status]);
95	
96	  const ask = useCallback(
97	    (question: string, byVoice = false) => {
98	      if (busy) return;
99	      stopSpeaking();
100	      voiceTurn.current = byVoice;
101	      clearError();
102	      void sendMessage({ text: question }, { body: { sessionId } });
103	    },
104	    [busy, clearError, sendMessage, sessionId],
105	  );
106	
107	  // A question asked by voice gets its answer read aloud once it's checked and complete (D127).
108	  useEffect(() => {
109	    if (status !== "ready" || !voiceTurn.current) return;
110	    voiceTurn.current = false;
111	    const last = messages.at(-1);
112	    const answer = last?.role === "assistant" ? last.parts.find((part) => part.type === "data-answer") : undefined;
113	    if (last && answer?.type === "data-answer") speak(last.id, answer.data.answer);
114	  }, [status, messages]);
115	
116	  const retryLast = useCallback(() => {
117	    const lastUser = [...messages].reverse().find((m) => m.role === "user");
118	    const question = textOf(lastUser);
119	    if (!question) return;
120	    setMessages(messages.slice(0, messages.lastIndexOf(lastUser!)));
121	    clearError();
122	    void sendMessage({ text: question }, { body: { sessionId } });
123	  }, [messages, setMessages, clearError, sendMessage, sessionId]);
124	
125	  const newChat = useCallback(() => {
126	    void stop();
127	    stopSpeaking();
128	    clearError();
129	    setMessages([]);
130	    setSessionId(null);
131	    setTab("chat");
132	  }, [stop, clearError, setMessages]);
133	
134	  const openChat = useCallback(
135	    async (id: string) => {
136	      setTab("chat");
137	      stopSpeaking();
138	      if (id === sessionId || busy) return;
139	      setLoadingChat(true);
140	      try {
141	        const res = await fetch(`/api/chat/history?sessionId=${id}`);
142	        if (!res.ok) throw new Error(await res.text());
143	        const { turns } = (await res.json()) as { turns: TranscriptTurn[] };
144	        clearError();
145	        setMessages(messagesFromTurns(turns));
146	        setSessionId(id);
147	      } catch {
148	        // keep the current chat; the side nav stays usable
149	      } finally {
150	        setLoadingChat(false);
151	      }
152	    },
153	    [busy, clearError, setMessages, sessionId],
154	  );
155	
156	
157	  /** Asking from the overview (or an alert) switches small screens to the conversation. */
158	  const askFromElsewhere = useCallback(
159	    (question: string) => {
160	      setTab("chat");
161	      ask(question);
162	    },
163	    [ask],
164	  );
165	
166	  const onStatus = useCallback((status: WidgetsData["dataStatus"]) => {
167	    setFreshness(`${status.hubCount} hubs · weather through ${status.weatherThrough}`);
168	    setHubCount(status.hubCount);
169	  }, []);
170	
171	  const lastAssistantId = [...messages].reverse().find((m) => m.role === "assistant")?.id;
172	  const completedAnswers = messages.filter((m) => m.parts.some((part) => part.type === "data-answer")).length;
173	
174	  // Small screens show one panel at a time (bottom tabs); desktop (xl, 1280 px+) shows all three (D125).
175	  const show = (panel: ShellTab) => (tab === panel ? "flex" : "hidden xl:flex");
176	
177	  return (
178	    <div className="flex h-dvh flex-col overflow-hidden">
179	      <Header freshness={freshness} />
180	
181	      <div className="mx-auto grid min-h-0 w-full max-w-[1680px] flex-1 grid-cols-[minmax(0,1fr)] grid-rows-[minmax(0,1fr)] gap-3 p-3 xl:grid-cols-[16rem_minmax(0,1fr)_22rem]">
182	        <Pane title="Your chats" className={show("chats")}>
183	          <SideNav sessionIds={sessionIds} activeId={sessionId} onOpen={(id) => void openChat(id)} onNew={newChat} refreshKey={completedAnswers} />
184	        </Pane>
185	
186	        <Pane
187	          title="Conversation"
188	          className={show("chat")}
189	          bodyRef={scrollRef}
190	          busy={loadingChat}
191	          footer={<Composer busy={busy} onSend={ask} onStop={() => void stop()} />}
192	        >
193	          <div className="space-y-4">
194	            {loadingChat && <p className="text-sm text-slate-400">Opening your chat…</p>}
195	            {messages.length === 0 && !loadingChat && <EmptyState onAsk={ask} hubCount={hubCount} />}
196	            {messages.map((message) =>
197	              message.role === "user" ? (
198	                <div key={message.id} className="flex justify-end">
199	                  <p className="max-w-[80%] rounded-2xl rounded-br-md bg-sky-400/15 px-4 py-2.5 text-[15px] text-slate-100">{textOf(message)}</p>
200	                </div>
201	              ) : (
202	                <AssistantMessage
203	                  key={message.id}
204	                  message={message}
205	                  isStreaming={busy && message.id === lastAssistantId}
206	                  onAsk={ask}
207	                  onRetry={retryLast}
208	                />
209	              ),
210	            )}
211	            {status === "submitted" && messages.at(-1)?.role === "user" && (
212	              <div className="glass rounded-2xl p-5 text-sm text-slate-400" aria-live="polite">
213	                Reading the question…
214	              </div>
215	            )}
216	            {error && <ErrorCard error={requestError(error)} onRetry={retryLast} />}
217	          </div>
218	        </Pane>
219	
220	        <Pane title="Overview" className={show("overview")}>
221	          <WidgetsRail onAsk={askFromElsewhere} onStatus={onStatus} />
222	          <Footer className="mt-3 px-1 xl:hidden" />
223	        </Pane>
224	      </div>
225	      <Footer className="hidden shrink-0 xl:block" />
226	      <TabBar tab={tab} onChange={setTab} className="xl:hidden" />
227	    </div>
228	  );
229	}
