1	/**
2	 * @module app/_lib/speech
3	 *
4	 * Voice (Step 15, bonus, D127), using only the browser: speech recognition to ask by
5	 * voice (Chrome, Edge, Safari) and speech synthesis to read answers aloud (all modern
6	 * browsers). No server, no cost, nothing recorded by us. Each feature is hidden where
7	 * the browser can't do it.
8	 *
9	 * Also a tiny "what is being read aloud right now" store, so every speaker button
10	 * shows the right state (useSyncExternalStore).
11	 */
12	
13	/** The parts of the Web Speech recognition API we use (not in every TS DOM lib). */
14	interface RecognitionResultEvent {
15	  resultIndex: number;
16	  results: ArrayLike<{ isFinal: boolean; 0: { transcript: string } }>;
17	}
18	
19	/** A speech recognizer. */
20	export interface Recognizer {
21	  start: () => void;
22	  stop: () => void;
23	}
24	
25	/** Events the recognizer reports. */
26	export interface RecognizerHandlers {
27	  /** The words heard so far in this session (interim and final). */
28	  onText: (text: string) => void;
29	  onEnd: () => void;
30	  /** A friendly message for the person (e.g. microphone blocked), and the browser's error code. */
31	  onError: (message: string, code: string) => void;
32	}
33	
34	type RecognitionCtor = new () => {
35	  lang: string;
36	  interimResults: boolean;
37	  continuous: boolean;
38	  onresult: ((event: RecognitionResultEvent) => void) | null;
39	  onend: (() => void) | null;
40	  onerror: ((event: { error: string }) => void) | null;
41	  start: () => void;
42	  stop: () => void;
43	};
44	
45	/** The browser's recognizer class, if any. */
46	function recognitionClass(): RecognitionCtor | null {
47	  if (typeof window === "undefined") return null;
48	  const w = window as unknown as { SpeechRecognition?: RecognitionCtor; webkitSpeechRecognition?: RecognitionCtor };
49	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
50	}
51	
52	/** @returns true when this browser can turn speech into text. */
53	export const canListen = (): boolean => recognitionClass() !== null;
54	
55	/** @returns true when this browser can read text aloud. */
56	export const canSpeak = (): boolean => typeof window !== "undefined" && "speechSynthesis" in window;
57	
58	/** Friendly messages for recognition errors (the rest are silent: the person just tries again). */
59	const RECOGNITION_ERRORS: Record<string, string> = {
60	  "not-allowed": "Microphone access is blocked. Allow it in your browser to ask by voice.",
61	  "service-not-allowed": "Microphone access is blocked. Allow it in your browser to ask by voice.",
62	  "no-speech": "I didn't catch anything. Try again, a little closer to the mic.",
63	  "audio-capture": "No microphone was found.",
64	  network: "Speech recognition needs an internet connection.",
65	};
66	
67	/**
68	 * Creates a one-shot recognizer (US English, live interim text).
69	 * @param handlers - text, end and error callbacks.
70	 * @returns the recognizer, or null when the browser can't listen.
71	 */
72	export function createRecognizer(handlers: RecognizerHandlers): Recognizer | null {
73	  const Recognition = recognitionClass();
74	  if (!Recognition) return null;
75	  const recognition = new Recognition();
76	  recognition.lang = "en-US";
77	  recognition.interimResults = true;
78	  recognition.continuous = false;
79	  recognition.onresult = (event) => {
80	    let text = "";
81	    for (let i = 0; i < event.results.length; i++) text += event.results[i][0].transcript;
82	    handlers.onText(text.trim());
83	  };
84	  recognition.onerror = (event) => {
85	    const message = RECOGNITION_ERRORS[event.error];
86	    if (message) handlers.onError(message, event.error);
87	  };
88	  recognition.onend = () => handlers.onEnd();
89	  return { start: () => recognition.start(), stop: () => recognition.stop() };
90	}
91	
92	/**
93	 * Turns an answer's Markdown into text that sounds natural when read aloud.
94	 * @param markdown - the answer text.
95	 * @returns plain, speakable text.
96	 */
97	export function speakableText(markdown: string): string {
98	  return markdown
99	    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1") // links → their text
100	    .replace(/[*_`#>]+/g, "") // emphasis, code, headings, quotes
101	    .replace(/^\s*[-•]\s+/gm, "") // list bullets
102	    .replace(/≥\s*/g, "at least ")
103	    .replace(/≤\s*/g, "at most ")
104	    .replace(/(\d)\s*–\s*(\d)/g, "$1 to $2") // ranges use an en dash: 0–100 → 0 to 100 (dates like 2021-01-01 stay intact)
105	    .replace(/\s*→\s*/g, " to ")
106	    .replace(/\s*·\s*/g, ", ")
107	    .replace(/\s*\n+\s*/g, ". ")
108	    .replace(/\.\s*\./g, ".")
109	    .replace(/[\p{Extended_Pictographic}\u{FE0F}\u{200D}]/gu, "") // emoji (🐱 would be read as "cat face")
110	    .replace(/\s{2,}/g, " ")
111	    .trim()
112	    // A closing "For example:" introduces clickable chips on screen, not words to read (D129).
113	    .replace(/\s*(for example|e\.g\.|such as)\s*:\s*$/i, "")
114	    .replace(/:\s*$/, ".");
115	}
116	
117	// --- What is being read aloud right now (one thing at a time) ---------------------------
118	
119	let speakingKey: string | null = null;
120	const listeners = new Set<() => void>();
121	const emit = () => listeners.forEach((listener) => listener());
122	
123	/** @returns the key of the answer being read aloud, or null. */
124	export const speakingSnapshot = (): string | null => speakingKey;
125	
126	/**
127	 * Subscribes to speaking changes (for useSyncExternalStore).
128	 * @param listener - called on every change.
129	 * @returns the unsubscribe function.
130	 */
131	export function subscribeSpeaking(listener: () => void): () => void {
132	  listeners.add(listener);
133	  return () => listeners.delete(listener);
134	}
135	
136	/** Stops reading aloud. */
137	export function stopSpeaking(): void {
138	  if (canSpeak()) window.speechSynthesis.cancel();
139	  speakingKey = null;
140	  emit();
141	}
142	
143	/**
144	 * Reads an answer aloud (stopping anything already playing).
145	 * @param key - identifies the answer (its message id), for the buttons' state.
146	 * @param markdown - the answer text.
147	 */
148	export function speak(key: string, markdown: string): void {
149	  if (!canSpeak()) return;
150	  window.speechSynthesis.cancel();
151	  const utterance = new SpeechSynthesisUtterance(speakableText(markdown));
152	  utterance.lang = "en-US";
153	  const done = () => {
154	    if (speakingKey === key) {
155	      speakingKey = null;
156	      emit();
157	    }
158	  };
159	  utterance.onend = done;
160	  utterance.onerror = done;
161	  speakingKey = key;
162	  emit();
163	  window.speechSynthesis.speak(utterance);
164	}
