1	"use client";
2	/**
3	 * The message box (U7): Enter sends, Shift+Enter adds a line, Stop while answering.
4	 *
5	 * Two ways to ask (D129): type, or conversation mode (the sound-waves button, hidden in browsers
6	 * that can't listen). Conversation mode is hands-free: listen → when you pause, send automatically
7	 * → the answer is read aloud → listen again. The mic stays off while the answer is being read, so
8	 * it never hears itself. Ends on a click, or when it hears nothing.
9	 */
10	import { useCallback, useEffect, useRef, useState, useSyncExternalStore, type FormEvent, type KeyboardEvent } from "react";
11	import { AGENT_LIMITS } from "@/core/agent/config";
12	import { canListen, createRecognizer, speakingSnapshot, stopSpeaking, subscribeSpeaking, type Recognizer } from "../_lib/speech";
13	
14	/** Longest message the API accepts — the agent's own limit (single source of truth). */
15	const MAX_CHARS = AGENT_LIMITS.maxUserMessageChars;
16	
17	/** How long a voice hint (e.g. "microphone blocked") stays visible. */
18	const HINT_MS = 6_000;
19	
20	/** Pause between the end of a read-aloud answer and listening again (conversation mode). */
21	const RELISTEN_DELAY_MS = 700;
22	
23	/** Support never changes during a visit, so there's nothing to subscribe to. */
24	const noSubscribe = () => () => {};
25	
26	/** Sound waves: conversation mode. */
27	function WavesIcon() {
28	  return (
29	    <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
30	      <path d="M4 10v4M8 6v12M12 3v18M16 7v10M20 10v4" />
31	    </svg>
32	  );
33	}
34	
35	/** Props for {@link Composer}. */
36	interface ComposerProps {
37	  busy: boolean;
38	  /** `byVoice` is true in conversation mode (the answer is then read aloud). */
39	  onSend: (text: string, byVoice: boolean) => void;
40	  onStop: () => void;
41	}
42	
43	/** Renders the composer. */
44	export function Composer({ busy, onSend, onStop }: ComposerProps) {
45	  const [text, setText] = useState("");
46	  const [listening, setListening] = useState(false);
47	  const [conversation, setConversation] = useState(false);
48	  const [voiceHint, setVoiceHint] = useState<string | null>(null);
49	  const recognizer = useRef<Recognizer | null>(null);
50	  const micSupported = useSyncExternalStore(noSubscribe, canListen, () => false);
51	  const speaking = useSyncExternalStore(subscribeSpeaking, speakingSnapshot, () => null) !== null;
52	  const tooLong = text.length > MAX_CHARS;
53	
54	  // Callbacks from the recognizer run later, so they read the latest values through refs.
55	  const conversationRef = useRef(false);
56	  const onSendRef = useRef(onSend);
57	  const heard = useRef("");
58	  const hadError = useRef(false);
59	  useEffect(() => {
60	    onSendRef.current = onSend;
61	  }, [onSend]);
62	
63	  useEffect(() => {
64	    if (!voiceHint) return;
65	    const timer = setTimeout(() => setVoiceHint(null), HINT_MS);
66	    return () => clearTimeout(timer);
67	  }, [voiceHint]);
68	
69	  useEffect(() => () => recognizer.current?.stop(), []);
70	
71	  /** Leaves conversation mode (and stops listening and speaking). */
72	  const endConversation = useCallback((hint?: string) => {
73	    conversationRef.current = false;
74	    setConversation(false);
75	    recognizer.current?.stop();
76	    stopSpeaking();
77	    if (hint) setVoiceHint(hint);
78	  }, []);
79	
80	  /** Starts one listening session: the question is sent when the person stops talking. */
81	  const startListening = useCallback(
82	    () => {
83	      heard.current = "";
84	      hadError.current = false;
85	      recognizer.current = createRecognizer({
86	        onText: (words) => {
87	          heard.current = words;
88	          setText(words);
89	        },
90	        onEnd: () => {
91	          setListening(false);
92	          if (!conversationRef.current) return;
93	          const question = heard.current.trim();
94	          if (question) {
95	            onSendRef.current(question, true);
96	            setText("");
97	          } else {
98	            // Nothing heard: leave conversation mode (a blocked mic already showed its own hint).
99	            endConversation(hadError.current ? undefined : "Conversation mode ended: I didn't hear anything.");
100	          }
101	        },
102	        onError: (message, code) => {
103	          // "Nothing heard" ends conversation mode with its own message; real problems keep their hint.
104	          if (code === "no-speech" && conversationRef.current) return;
105	          hadError.current = true;
106	          setVoiceHint(message);
107	        },
108	      });
109	      if (!recognizer.current) return;
110	      setVoiceHint(null);
111	      setListening(true);
112	      recognizer.current.start();
113	    },
114	    [endConversation],
115	  );
116	
117	  // Conversation loop: whenever nothing is being sent or read aloud, listen for the next question.
118	  useEffect(() => {
119	    if (!conversation || busy || speaking || listening) return;
120	    const timer = setTimeout(startListening, RELISTEN_DELAY_MS);
121	    return () => clearTimeout(timer);
122	  }, [conversation, busy, speaking, listening, startListening]);
123	
124	  const toggleConversation = () => {
125	    if (conversation) {
126	      endConversation();
127	      return;
128	    }
129	    recognizer.current?.stop();
130	    stopSpeaking();
131	    conversationRef.current = true;
132	    setConversation(true);
133	  };
134	
135	  const submit = (event?: FormEvent) => {
136	    event?.preventDefault();
137	    const trimmed = text.trim();
138	    if (!trimmed || busy || tooLong) return;
139	    recognizer.current?.stop();
140	    onSend(trimmed, false);
141	    setText("");
142	  };
143	  const onKeyDown = (event: KeyboardEvent<HTMLTextAreaElement>) => {
144	    if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
145	      event.preventDefault();
146	      submit();
147	    }
148	  };
149	
150	  const conversationStatus = listening
151	    ? "Listening… just talk, I'll send it when you pause."
152	    : busy
153	      ? "Getting the answer…"
154	      : speaking
155	        ? "Reading the answer. I'll listen again when it's done."
156	        : "Getting ready to listen…";
157	
158	  return (
159	    <div>
160	      {conversation && (
161	        <p role="status" className="mb-2 flex items-center gap-2 px-2 text-xs text-sky-200">
162	          <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-sky-300 motion-reduce:animate-none" aria-hidden="true" />
163	          Conversation mode · {conversationStatus}
164	        </p>
165	      )}
166	      {voiceHint && (
167	        <p role="status" className="mb-2 px-2 text-xs text-amber-300">
168	          {voiceHint}
169	        </p>
170	      )}
171	      <form onSubmit={submit} className="glass flex items-end gap-2 rounded-2xl bg-slate-950/85 p-2 shadow-lg shadow-black/40">
172	        <label htmlFor="question" className="sr-only">
173	          Your question
174	        </label>
175	        <textarea
176	          id="question"
177	          rows={1}
178	          value={text}
179	          onChange={(event) => setText(event.target.value)}
180	          onKeyDown={onKeyDown}
181	          placeholder={listening ? "Listening… ask your question" : "Ask about a hub, hazard or region…"}
182	          className="max-h-40 min-h-10 flex-1 resize-none bg-transparent px-3 py-2 text-[15px] text-slate-100 placeholder:text-slate-500 focus:outline-none"
183	          aria-describedby={tooLong ? "too-long" : undefined}
184	        />
185	        {tooLong && (
186	          <span id="too-long" className="self-center text-xs text-amber-300">
187	            {text.length}/{MAX_CHARS}
188	          </span>
189	        )}
190	        {micSupported && (
191	          <button
192	            type="button"
193	            onClick={toggleConversation}
194	            aria-pressed={conversation}
195	            aria-label={conversation ? "End conversation mode" : "Start conversation mode (hands-free)"}
196	            title={conversation ? "End conversation mode" : "Conversation mode: talk hands-free, answers are read aloud"}
197	            className={`rounded-xl px-3 py-2 text-sm transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60 ${
198	              conversation ? "bg-sky-400/90 text-slate-950 hover:bg-sky-300" : "border border-white/15 text-slate-300 hover:bg-white/10"
199	            }`}
200	          >
201	            <WavesIcon />
202	          </button>
203	        )}
204	        {busy ? (
205	          <button
206	            type="button"
207	            onClick={onStop}
208	            className="rounded-xl border border-white/15 px-4 py-2 text-sm text-slate-200 transition hover:bg-white/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
209	          >
210	            Stop
211	          </button>
212	        ) : (
213	          <button
214	            type="submit"
215	            disabled={!text.trim() || tooLong}
216	            className="rounded-xl bg-sky-400/90 px-4 py-2 text-sm font-medium text-slate-950 transition hover:bg-sky-300 disabled:cursor-not-allowed disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-200"
217	          >
218	            Ask
219	          </button>
220	        )}
221	      </form>
222	    </div>
223	  );
224	}
