24	/** Renders the card, or nothing when there's nothing new. */
25	export function RecentChanges({ onAsk }: RecentChangesProps) {
26	  const [alerts, setAlerts] = useState<RecentAlert[]>([]);
27	  const dismissed = useSyncExternalStore(subscribeToStorage, dismissedAlertsSnapshot, () => EMPTY_IDS);
28	
29	  useEffect(() => {
30	    let alive = true;
31	    fetch("/api/alerts")
32	      .then((res) => (res.ok ? (res.json() as Promise<{ alerts: RecentAlert[] }>) : Promise.reject(new Error(String(res.status)))))
33	      .then((json) => alive && setAlerts(json.alerts))
34	      .catch(() => {
35	        // Quiet on failure: alerts are extra information, the rest of the overview still works.
36	      });
37	    return () => {
38	      alive = false;
39	    };
40	  }, []);
41	
42	  const visible = alerts.filter((alert) => !dismissed.includes(alert.id));
43	  if (visible.length === 0) return null;
44	
45	  return (
46	    <section className="rounded-xl border border-amber-400/30 bg-amber-400/[0.04] px-3 py-2.5" aria-label="Recent changes">
47	      <h3 className="flex items-center gap-2 text-sm font-medium text-amber-200">
48	        <span aria-hidden="true">🔔</span> Recent changes
49	      </h3>
50	      <p className="mb-1.5 mt-0.5 text-[11px] leading-snug text-slate-400">Overnight: a risk level changed or a score moved 10+ points.</p>
51	      <ul className="space-y-1.5">
52	        {visible.map((alert) => (
53	          <li key={alert.id} className="flex items-start gap-2 rounded-lg bg-white/[0.03] px-2 py-1.5">
54	            <button
55	              type="button"
56	              className="flex-1 text-left text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
57	              onClick={() => onAsk(`Why is ${alert.hubName}'s weather risk ${LEVEL_UI[alert.toLevel].label.toLowerCase()}?`)}
58	            >
59	              <span className="text-slate-100">{alert.hubName}</span>{" "}
60	              {alert.test && <span className="ml-1 rounded bg-slate-600/60 px-1.5 py-0.5 text-[10px] uppercase tracking-wide text-slate-200">test</span>}
61	              <span className="block text-xs text-slate-400">
62	                {describe(alert)} · {relativeTime(alert.createdAt)}
63	                {alert.test ? " · not a real change" : ""}
64	              </span>
65	            </button>
66	            <button
67	              type="button"
68	              aria-label={`Dismiss the ${alert.hubName} alert`}
69	              className="rounded px-1.5 text-slate-500 transition hover:bg-white/10 hover:text-slate-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
70	              onClick={() => dismissAlert(alert.id)}
71	            >
72	              ✕
73	            </button>
74	          </li>
75	        ))}
76	      </ul>
77	    </section>
78	  );
79	}
