56	/**
57	 * Reads the NDJSON progress stream line by line.
58	 * @param response - the streaming response.
59	 * @param onEvent - called for each event.
60	 */
61	async function readEvents(response: Response, onEvent: (event: SuiteEvent | { type: "error"; message: string }) => void): Promise<void> {
62	  const reader = response.body!.pipeThrough(new TextDecoderStream()).getReader();
63	  let buffer = "";
64	  for (;;) {
65	    const { value, done } = await reader.read();
66	    if (done) break;
67	    buffer += value;
68	    const lines = buffer.split("\n");
69	    buffer = lines.pop() ?? "";
70	    for (const line of lines) if (line.trim()) onEvent(JSON.parse(line));
71	  }
72	}
