74	/**
75	 * The status line of a run.
76	 * @param summary - the run.
77	 * @returns e.g. "12 of 13 passed".
78	 */
79	const passedText = (summary: EvalRunSummary) => `${summary.passed} of ${summary.total} passed`;
80	
81	/**
82	 * Loads the last run and the limit status.
83	 * @returns the data.
84	 * @throws when the request fails.
85	 */
86	async function fetchLatest(): Promise<LatestRun> {
87	  const res = await fetch("/api/evals/latest", { signal: AbortSignal.timeout(15_000) });
88	  if (!res.ok) throw new Error(String(res.status));
89	  return (await res.json()) as LatestRun;
90	}
