92	/** One line in the overview's "About the data", opening the dialog. */
93	export function EvalQualityRow() {
94	  const [data, setData] = useState<LatestRun | null>(null);
95	  const [failed, setFailed] = useState(false);
96	  const [open, setOpen] = useState(false);
97	
98	  const load = useCallback(
99	    () =>
100	      fetchLatest().then(
101	        (latest) => {
102	          setData(latest);
103	          setFailed(false);
104	        },
105	        () => setFailed(true),
106	      ),
107	    [],
108	  );
109	
110	  useEffect(() => {
111	    let alive = true;
112	    fetchLatest().then(
113	      (latest) => alive && setData(latest),
114	      () => alive && setFailed(true),
115	    );
116	    return () => {
117	      alive = false;
118	    };
119	  }, []);
120	
121	  // While someone's run is in progress (and this browser isn't streaming it), check back now and then.
122	  useEffect(() => {
123	    if (!data?.status.running || open) return;
124	    const timer = setInterval(() => void load(), POLL_MS);
125	    return () => clearInterval(timer);
126	  }, [data?.status.running, open, load]);
127	
128	  const latest = data?.latest ?? null;
129	  const summaryText = failed
130	    ? "Couldn't load"
131	    : !data
132	      ? "…"
133	      : data.status.running
134	        ? "Running now…"
135	        : latest
136	          ? `${latest.passed}/${latest.total} passed · ${relativeTime(latest.finishedAt)}`
137	          : "Not run yet";
138	  return (
139	    <>
140	      <div className="col-span-2 -mx-1">
141	        <button
142	          type="button"
143	          onClick={() => setOpen(true)}
144	          className="flex w-full items-center justify-between gap-2 rounded-md px-1 text-left transition hover:bg-white/5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
145	          aria-haspopup="dialog"
146	        >
147	          <span>Answer quality</span>
148	          <span className="flex items-center gap-1 text-right text-slate-300">
149	            {latest && !data?.status.running && <span aria-hidden="true">{latest.passed === latest.total ? "✅" : "⚠️"}</span>}
150	            {summaryText}
151	            <span aria-hidden="true" className="text-slate-500">›</span>
152	          </span>
153	        </button>
154	      </div>
155	      {open && (
156	        <EvalRunDialog
157	          data={data}
158	          onClose={() => {
159	            setOpen(false);
160	            void load();
161	          }}
162	          onFinished={() => void load()}
163	        />
164	      )}
165	    </>
166	  );
167	}
