169	/** Props for {@link EvalRunDialog}. */
170	interface EvalRunDialogProps {
171	  data: LatestRun | null;
172	  onClose: () => void;
173	  /** Called when a run started here ends, so the overview line refreshes. */
174	  onFinished: () => void;
175	}
