177	/** The dialog: what the evals are, the last run, and the live run. */
178	function EvalRunDialog({ data, onClose, onFinished }: EvalRunDialogProps) {
179	  const ref = useRef<HTMLDialogElement>(null);
180	  const [live, setLive] = useState<LiveRun | null>(null);
181	  const [starting, setStarting] = useState(false);
182	  const [refused, setRefused] = useState<{ message: string; status: EvalGateStatus | null } | null>(null);
183	  /** "Run evals" first asks for confirmation and lists the limits; only "Yes, start" runs. */
184	  const [confirming, setConfirming] = useState(false);
185	
186	  useEffect(() => {
187	    const dialog = ref.current;
188	    if (dialog && !dialog.open) dialog.showModal();
189	  }, []);
190	
191	  const run = async () => {
192	    setConfirming(false);
193	    setStarting(true);
194	    setRefused(null);
195	    let streaming = false;
196	    try {
197	      const res = await fetch("/api/evals/run", { method: "POST" });
198	      if (!res.ok || !res.body) {
199	        const body = (await res.json().catch(() => null)) as { error?: { message?: string; hint?: string }; status?: EvalGateStatus } | null;
200	        setRefused({ message: [body?.error?.message, body?.error?.hint].filter(Boolean).join(" ") || "The evals couldn't start right now. Please try again later.", status: body?.status ?? null });
201	        return;
202	      }
203	      streaming = true;
204	      setLive({ cases: [], done: {}, selfTest: null, summary: null, error: null });
205	      await readEvents(res, (event) =>
206	        setLive((current) => {
207	          const state = current ?? { cases: [], done: {}, selfTest: null, summary: null, error: null };
208	          if (event.type === "start") return { ...state, cases: event.cases };
209	          if (event.type === "selftest") return { ...state, selfTest: { correct: event.correct, total: event.total } };
210	          if (event.type === "case") return { ...state, done: { ...state.done, [event.outcome.caseId]: event.outcome } };
211	          if (event.type === "done") return { ...state, summary: event.summary };
212	          return { ...state, error: event.message };
213	        }),
214	      );
215	      setLive((current) => (current && !current.summary && !current.error ? { ...current, error: "The connection dropped before the run finished. The results may still show up here in a few minutes." } : current));
216	    } catch {
217	      setLive((current) => (current ? { ...current, error: "The connection dropped before the run finished. The results may still show up here in a few minutes." } : current));
218	      if (!streaming) setRefused({ message: "The evals couldn't start right now. Please check your connection and try again.", status: null });
219	    } finally {
220	      setStarting(false);
221	      onFinished();
222	    }
223	  };
224	
225	  const status = refused?.status ?? data?.status ?? null;
226	  const isRunningHere = Boolean(live && !live.summary && !live.error);
227	  // While this browser streams a run, the footer talks about that run; otherwise it says when the next one is possible.
228	  const blocked = isRunningHere ? null : status ? blockedReason(status) : null;
229	  const shown = live?.summary ?? (live ? null : (data?.latest ?? null));
230	
231	  return (
232	    <dialog
233	      ref={ref}
234	      onClose={onClose}
235	      onClick={(e) => e.target === ref.current && ref.current?.close()}
236	      className="m-auto w-[min(34rem,calc(100vw-2rem))] max-h-[min(44rem,calc(100dvh-2rem))] overflow-hidden rounded-2xl border border-white/10 bg-[#0e1428] p-0 text-slate-200 shadow-2xl backdrop:bg-black/60 backdrop:backdrop-blur-sm"
237	      aria-labelledby="eval-dialog-title"
238	    >
239	      <div className="flex max-h-[inherit] flex-col">
240	        <header className="flex items-start justify-between gap-3 border-b border-white/[0.06] px-5 py-4">
241	          <div>
242	            <h2 id="eval-dialog-title" className="text-base font-semibold text-slate-100">Answer quality</h2>
243	            <p className="mt-1 text-xs leading-relaxed text-slate-400">
244	              {data?.caseCount ?? "A set of"} test questions whose right answers we know from our own data. Each answer is checked by code (numbers, rankings,
245	              honesty about weak data) and by an independent AI judge. A run takes 1–2 minutes.
246	            </p>
247	          </div>
248	          <button type="button" onClick={() => ref.current?.close()} className="rounded-md px-2 py-1 text-slate-400 transition hover:bg-white/5 hover:text-slate-200" aria-label="Close">
249	            ✕
250	          </button>
251	        </header>
252	
253	        <div className="min-h-0 flex-1 overflow-y-auto px-5 py-4">
254	          {confirming ? (
255	            <ConfirmRun runsLeftToday={status?.runsLeftToday ?? EVAL_RUN_LIMITS.runsPerDay} />
256	          ) : live ? (
257	            <LiveProgress live={live} />
258	          ) : shown ? (
259	            <RunDetails summary={shown} />
260	          ) : (
261	            <p className="text-sm text-slate-400">No run has been saved yet. Start the first one below.</p>
262	          )}
263	        </div>
264	
265	        <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-white/[0.06] px-5 py-3">
266	          <p className="min-w-0 flex-1 text-[11px] leading-snug text-slate-400">
267	            {confirming
268	              ? "Start the run?"
269	              : (refused?.message ??
270	                (isRunningHere
271	                  ? "You can close this window. The run keeps going and its results will show up here."
272	                  : blocked ?? (status ? `Shared limit: one run every ${EVAL_RUN_LIMITS.minutesBetweenRuns} minutes, ${status.runsLeftToday} of ${EVAL_RUN_LIMITS.runsPerDay} left today.` : "")))}
273	          </p>
274	          {confirming ? (
275	            <span className="flex gap-2">
276	              <button type="button" onClick={() => setConfirming(false)} className="rounded-lg px-3.5 py-1.5 text-sm text-slate-300 transition hover:bg-white/5">
277	                Cancel
278	              </button>
279	              <button type="button" onClick={() => void run()} className="rounded-lg bg-sky-500/90 px-3.5 py-1.5 text-sm font-medium text-white transition hover:bg-sky-400">
280	                Yes, start the run
281	              </button>
282	            </span>
283	          ) : (
284	            <button
285	              type="button"
286	              onClick={() => setConfirming(true)}
287	              disabled={starting || isRunningHere || Boolean(blocked) || Boolean(live?.summary)}
288	              className="rounded-lg bg-sky-500/90 px-3.5 py-1.5 text-sm font-medium text-white transition hover:bg-sky-400 disabled:bg-white/10 disabled:text-slate-400"
289	            >
290	              {starting ? "Starting…" : isRunningHere ? "Running…" : live?.summary ? "Done ✓" : "Run evals…"}
291	            </button>
292	          )}
293	        </footer>
294	      </div>
295	    </dialog>
296	  );
297	}
