41	
42	/** Renders the final answer card. */
43	export function FinalAnswerCard({ answer, speechKey, onAsk }: FinalAnswerCardProps) {
44	  const visuals = pickVisuals(answer);
45	  const steps = [...new Set(answer.meta.toolCalls.map((c) => progressLabel(c.tool, c.input).replace(/…$/, "")))];
46	  const caveats = [...answer.assumptions, ...answer.limitations];
47	
48	  return (
49	    <div className="space-y-4">
50	      {answer.premiseCheck && <PremiseBanner check={answer.premiseCheck} />}
51	      <Markdown text={answer.answer} />
52	
53	      {visuals.map((visual) => (
54	        <div key={visual.key} className="rounded-xl border border-white/5 bg-black/15 p-4">
55	          <Visual visual={visual} />
56	        </div>
57	      ))}
58	
59	      {answer.recommendation && <RecommendationBox recommendation={answer.recommendation} />}
60	
61	      <div className="flex items-center gap-2">
62	        {answer.confidence && (
63	          <p className="flex items-center gap-2 text-xs text-slate-400" title="Computed by code from data completeness and whether the sources agree">
64	            <span className="h-2 w-2 rounded-full" style={{ background: CONFIDENCE_UI[answer.confidence].dot }} aria-hidden="true" />
65	            {CONFIDENCE_UI[answer.confidence].label}
66	          </p>
67	        )}
68	        <SpeakButton speechKey={speechKey} text={answer.answer} />
69	      </div>
70	
71	      {(caveats.length > 0 || steps.length > 0) && (
72	        <div className="space-y-2">
73	          {caveats.length > 0 && (
74	            <Disclosure summary={`Assumptions & limits (${caveats.length})`}>
75	              <ul className="list-disc space-y-1 pl-5 text-[13px] leading-snug">
76	                {caveats.map((text) => (
77	                  <li key={text}>{text}</li>
78	                ))}
79	              </ul>
80	            </Disclosure>
81	          )}
82	          {steps.length > 0 && (
83	            <Disclosure summary="How I got this">
84	              <ul className="space-y-1 text-[13px]">
85	                {steps.map((step) => (
86	                  <li key={step}>✓ {step}</li>
87	                ))}
88	              </ul>
89	              <p className="mt-2 text-xs text-slate-500">
90	                Every number above was checked against these results before you saw it
91	                {answer.meta.retried ? " (the first draft failed that check and was corrected)" : ""}.
92	              </p>
93	              {answer.meta.warnings.length > 0 && (
94	                <p className="mt-1 text-xs text-amber-300/80">
95	                  Note: {answer.meta.warnings.length} number{answer.meta.warnings.length > 1 ? "s" : ""} in the text could not be traced to
96	                  the data tools — treat {answer.meta.warnings.length > 1 ? "them" : "it"} with care.
97	                </p>
98	              )}
99	            </Disclosure>
100	          )}
101	        </div>
102	      )}
103	
104	      {answer.followUpSuggestions.length > 0 && (
105	        <div className="flex flex-wrap gap-2" aria-label="Suggested follow-up questions">
106	          {answer.followUpSuggestions.map((question) => (
107	            <button
108	              key={question}
109	              type="button"
110	              onClick={() => onAsk(question)}
111	              className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-1 text-xs text-slate-300 transition hover:border-sky-300/40 hover:text-slate-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-sky-400/60"
112	            >
113	              {question}
114	            </button>
115	          ))}
116	        </div>
117	      )}
118	    </div>
